def parse(art):
    rows = art
    assert len(rows) == 16, 'row!=16'
    m = []
    for r in rows:
        r = r.strip()
        assert len(r) == 16, 'col!=16: ' + r
        m.append([255 if c == '#' else 0 for c in r])
    return m

def md5hex(s):
    return hashlib.md5(s.encode('utf-8')).hexdigest()

def main():
    records = []
    seen = {}
    for ch, art in GLYPHS.items():
        m = parse(art)
        flat = tuple(tuple(row) for row in m)
        assert flat not in seen, 'dup glyph ' + ch
        seen[flat] = ch
        assert any(v == 255 for row in m for v in row), 'empty ' + ch
        records.append({
            'schema_version': SCHEMA,
            'timestamp': time.time(),
            'char': ch,
            'width': 16,
            'height': 16,
            'matrix': m,
            'source': SOURCE,
        })

    n = len(records)
    print('[STEP211] total glyphs =', n)
    assert n >= 100, 'need >=100'

    with open(OUT, 'w', encoding='utf-8') as f:
        for rec in records:
            f.write(json.dumps(rec, ensure_ascii=False) + chr(10))

    with open(OUT, 'rb') as f:
        file_hash = hashlib.md5(f.read()).hexdigest()
    print('[STEP211] written', OUT)
    print('[STEP211] file_md5 =', file_hash)
    print('[STEP211] records =', n)

    lines = open(CHAIN, encoding='utf-8').read().strip().splitlines()
    tail = json.loads(lines[-1])
    prev_hash = tail['record_hash']
    ts = time.time()
    record_hash = md5hex(file_hash + prev_hash + str(ts))
    entry = {
        'schema_version': SCHEMA,
        'timestamp': ts,
        'file': OUT,
        'file_hash': file_hash,
        'prev_hash': prev_hash,
        'record_hash': record_hash,
    }
    with open(CHAIN, 'a', encoding='utf-8') as f:
        f.write(json.dumps(entry, ensure_ascii=False) + chr(10))
    print('[STEP211] prev_hash =', prev_hash)
    print('[STEP211] record_hash =', record_hash)
    print('[STEP211] chain appended')

    print()
    print('===== FIRST 10 chars =====')
    print(' '.join(r['char'] for r in records[:10]))
    print('===== LAST 10 chars =====')
    print(' '.join(r['char'] for r in records[-10:]))
    print()
    print('===== CHAIN TAIL 3 =====')
    for l in open(CHAIN, encoding='utf-8').read().strip().splitlines()[-3:]:
        print(l)
    print()
    print('===== md5sum =====')
    print(file_hash, ' ', OUT)
    print()
    print('===== ls -l =====')
    for p in [OUT, 'hanzi_matrix_from_llm.py', CHAIN]:
        try:
            st = os.stat(p)
            print(str(st.st_size).rjust(10), ' ', p)
        except FileNotFoundError:
            print('   missing ', p)

if __name__ == '__main__':
    main()
